/**
 * WHY: path resolution drops a trailing separator, so `write` to `dir/` created a FILE named
 * `dir`, after which every `dir/<file>` write failed with ENOTDIR, and `write` to `file.ts/`
 * replaced `file.ts`; `write` to an existing directory surfaced a raw
 * `EISDIR: illegal operation on a directory, read` from the auto-generated probe, or a different
 * raw errno once `edit.blockAutoGenerated` skips that probe.
 *
 * Class closed: every spelling of a directory target (existing or new, bare or with a trailing
 * separator, relative, absolute, `.`, and a `local://` sandbox path) is rejected with one message
 * that gives the file path to use, leaves the tree untouched, and does so with the auto-generated
 * probe on and off. An existing file spelled with a trailing separator keeps its bytes. A file path
 * inside a directory still writes, and a path through a file still fails as a write failure.
 *
 * Not caught: a trailing backslash, which separates only on Windows and is a legal filename
 * character elsewhere; this suite runs the POSIX spelling.
 */
import { afterAll, afterEach, beforeAll, beforeEach, describe, expect, it } from "bun:test";
import * as fs from "node:fs/promises";
import * as os from "node:os";
import * as path from "node:path";
import { Settings } from "@veyyon/coding-agent/config/settings";
import { WriteTool } from "@veyyon/coding-agent/tools/fs/write";
import { removeWithRetries } from "@veyyon/utils";
import { beginSettingsTest, restoreSettingsTestState, type SettingsTestState } from "../helpers/settings-test-state";
import { makeToolSession } from "../helpers/tool-session";

/** Each spelling of a directory target, with the directory part the error suggests a file under. */
const DIRECTORY_SPELLINGS: Array<{ label: string; target: (root: string) => string; base: (root: string) => string }> =
	[
		{ label: "an existing directory", target: () => "sub", base: () => "sub" },
		{ label: "an existing directory with a trailing slash", target: () => "sub/", base: () => "sub" },
		{ label: "a new path with a trailing slash", target: () => "fresh/", base: () => "fresh" },
		{ label: "a new nested path with a trailing slash", target: () => "a/b/", base: () => "a/b" },
		{ label: "the working directory", target: () => ".", base: () => "." },
		{
			label: "an absolute existing directory",
			target: root => path.join(root, "sub"),
			base: root => path.join(root, "sub"),
		},
		{ label: "a local:// path with a trailing slash", target: () => "local://notes/", base: () => "local://notes" },
	];

/** Every path under `root`, so a run that creates anything shows up as a difference. */
async function tree(root: string): Promise<string[]> {
	return (await fs.readdir(root, { recursive: true })).sort();
}

for (const blockAutoGenerated of [true, false]) {
	describe(`a write aimed at a directory creates nothing (edit.blockAutoGenerated: ${blockAutoGenerated})`, () => {
		let settingsState: SettingsTestState | undefined;
		let tmpDir: string;

		beforeAll(async () => {
			settingsState = beginSettingsTest();
			await Settings.init({ inMemory: true, overrides: { "edit.blockAutoGenerated": blockAutoGenerated } });
		});

		afterAll(() => {
			restoreSettingsTestState(settingsState);
			settingsState = undefined;
		});

		beforeEach(async () => {
			tmpDir = await fs.mkdtemp(path.join(os.tmpdir(), "write-dir-"));
			await fs.mkdir(path.join(tmpDir, "sub"));
			await fs.mkdir(path.join(tmpDir, "artifacts", "local"), { recursive: true });
		});

		afterEach(async () => {
			await removeWithRetries(tmpDir);
		});

		function writeTool(): WriteTool {
			return new WriteTool(
				makeToolSession({
					cwd: tmpDir,
					hasUI: false,
					getSessionFile: () => path.join(tmpDir, "session.jsonl"),
					getSessionSpawns: () => "*",
					getArtifactsDir: () => path.join(tmpDir, "artifacts"),
					allocateOutputArtifact: async () => ({ id: "r", path: path.join(tmpDir, "r.log") }),
					settings: Settings.isolated({
						"lsp.formatOnWrite": false,
						"lsp.diagnosticsOnWrite": false,
						"edit.blockAutoGenerated": blockAutoGenerated,
					}),
					enableLsp: false,
					getPlanModeState: () => ({ enabled: false }),
				}),
			);
		}

		for (const { label, target, base } of DIRECTORY_SPELLINGS) {
			it(`rejects ${label} and gives the file path to use`, async () => {
				const before = await tree(tmpDir);
				const spelled = target(tmpDir);

				await expect(writeTool().execute("w", { path: spelled, content: "x" })).rejects.toThrow(
					`'${spelled}' is a directory path; write creates or replaces a file. Give the file's path, such as '${base(tmpDir)}/<name>'.`,
				);
				expect(await tree(tmpDir)).toEqual(before);
			});
		}

		it("writes a file inside the directory", async () => {
			await writeTool().execute("w", { path: "sub/file.txt", content: "body\n" });
			expect(await fs.readFile(path.join(tmpDir, "sub", "file.txt"), "utf8")).toBe("body\n");
		});

		it("leaves an existing file as it was when its path is spelled with a trailing slash", async () => {
			await fs.writeFile(path.join(tmpDir, "kept.txt"), "original\n");

			await expect(writeTool().execute("w", { path: "kept.txt/", content: "replaced\n" })).rejects.toThrow(
				"'kept.txt/' ends in a path separator, but 'kept.txt' is a file; write to 'kept.txt' to replace it.",
			);
			expect(await fs.readFile(path.join(tmpDir, "kept.txt"), "utf8")).toBe("original\n");
		});

		it("fails a path through a file as a write failure naming the path", async () => {
			await fs.writeFile(path.join(tmpDir, "kept.txt"), "original\n");
			const target = path.join(tmpDir, "kept.txt", "x.txt");

			await expect(writeTool().execute("w", { path: target, content: "y\n" })).rejects.toThrow(
				`Failed to write ${target}: ENOTDIR`,
			);
		});
	});
}
